        bases.add('[$marker] body=${body.length}ch (unparsed)');
      }
      if (marker == 'continuation') {
        await Future<void>.delayed(const Duration(milliseconds: 2500));
      }
      final chunks = switch (marker) {
        'judge' => ['[2]'],
        'summarizer' => ['checkpoint: probe'],
        'E1' => ['hi!'],
        'continuation' => ['done: recovered'],
        _ => [
          jsonEncode({
            'id': 'chatcmpl-x',
            'object': 'chat.completion.chunk',
            'choices': [
              {
                'index': 0,
                'delta': {
                  'role': 'assistant',
                  'tool_calls': [
                    for (var i = 1; i <= 30; i++)
                      {
                        'index': i - 1,
                        'id': 'call_$i',
                        'type': 'function',
                        'function': {
                          'name': 'read',
                          'arguments': '{"path": "big$i.txt"}',
                        },
                      },
                  ],
                },
                'finish_reason': null,
              },
            ],
          }),
        ],
      };
      final response = request.response;
      response.headers.contentType = ContentType('text', 'event-stream');
      for (final c in chunks) {
        response.write('data: $c\n\n');
      }
      response.write(
        'data: ${jsonEncode({
          'id': 'chatcmpl-x',
          'object': 'chat.completion.chunk',
          'choices': [
            {'index': 0, 'delta': {}, 'finish_reason': 'stop'},
          ],
        })}\n\n',
      );
      response.write('data: [DONE]\n\n');
      await response.close();
    });

    final tempHome = Directory.systemTemp.createTempSync('fa_probe_');
    File('${tempHome.path}/.fah/config.yaml')
      ..createSync(recursive: true)
      ..writeAsStringSync('''
provider: openai-completions
model: test-model
baseUrl: http://127.0.0.1:${server.port}/v1
mode: code
approvalMode: yolo
allowedTools: [read]
tui:
  classic: true
agent:
  contextWindowCap: 16384
''');
    final workspace = Directory('/tmp').createTempSync('faprobe');
    for (var i = 1; i <= 30; i++) {
      File(
        '${workspace.path}/big$i.txt',
      ).writeAsStringSync(List.filled(60, 'x' * 40).join('\n'));
    }
    final harness = await FaCliHarness.spawn(
      workingDirectory: workspace.path,
      extraEnv: {'HOME': tempHome.path, 'OPENAI_API_KEY': 'test-key'},
    );
    harness.sendText('count the words');
    harness.sendEnter();
    // Wait for the turn-1 fold to settle (receipt + recovered marker).
    await harness.waitForText(
      'done: recovered',
      timeout: const Duration(seconds: 120),
    );
    bases.add('--- E1 turn ---');
    harness.sendText('say hi');
    harness.sendEnter();
    // Give E1's request time to hit the mock, then dump.
    await Future<void>.delayed(const Duration(seconds: 12));
    for (final b in bases) {
      stderr.writeln('PROBE $b');
    }
    await harness.close();
    tempHome.deleteSync(recursive: true);
    workspace.deleteSync(recursive: true);
    await server.close(force: true);
  }, timeout: const Timeout(Duration(minutes: 5)));
}
"}

