void main() {
  test('probe: request token composition', () async {
    final server = await HttpServer.bind('127.0.0.1', 0);
    final bases = <String>[];
    server.listen((request) async {
      if (request.method == 'GET' && request.uri.path.endsWith('/models')) {
        request.response.headers.contentType = ContentType.json;
        request.response.write(jsonEncode({'object': 'list', 'data': []}));
        await request.response.close();
        return;
      }
      final body = await utf8.decoder.bind(request).join();
      final marker = switch (body) {
        final b when b.contains('context-hygiene judge') => 'judge',
        final b when b.contains('<conversation>') => 'summarizer',
        final b when b.contains('say hi') => 'E1',
        final b when b.contains('checkpoint:') => 'continuation',
        _ => 'reads',
      };
      // Rough per-message decomposition of the request body.
      try {
        final json = jsonDecode(body) as Map<String, dynamic>;
        final messages = (json['messages'] as List?) ?? const [];
        final parts = <String>[];
        for (final m in messages) {
          final role = m['role'];
          final content = m['content'];
          final text = content is String
              ? content
              : jsonEncode(content);
          parts.add('$role:${estimateStringTokens(text)}');
        }
        final sysMatch = RegExp(r'"system":"((?:[^"\\]|\\.)*)"').firstMatch(body);
        final sysTokens = sysMatch == null
            ? -1
            : estimateStringTokens(sysMatch.group(1)!);
        bases.add(
          '[$marker] body=${body.length}ch sys≈$sysTokens '
          'msgs=[${parts.join(", ")}]',
        );
      } catch (_) {
        bases.add('[$marker] body=${body.length}ch (unparsed)');
      }
      if (marker == 'continuation') {
        await Future<void>.delayed(const Duration(milliseconds: 2500));
      }
      final chunks = switch (marker) {
        'judge' => ['[2]'],
        'summarizer' => ['checkpoint: probe'],
        'E1' => ['hi!'],
        'continuation' => ['done: recovered'],
        _ => [
          jsonEncode({
            'id': 'chatcmpl-x',
            'object': 'chat.completion.chunk',
            'choices': [
              {
                'index': 0,
                'delta': {
                  'role': 'assistant',
                  'tool_calls': [
                    for (var i = 1; i <= 30; i++)
                      {
                        'index': i - 1,
                        'id': 'call_$i',
                        'type': 'function',
                        'function': {
                          'name': 'read',
                          'arguments': '{"path": "big$i.txt"}',
                        },
                      },
                  ],
                },
                'finish_reason': null,
              },
            ],
          }),
        ],
      };
      final response = request.response;
      response.headers.contentType = ContentType('text', 'event-stream');
      for (final c in chunks) {
        response.write('data: $c\n\n');
      }
      response.write(
        'data: ${jsonEncode({
          'id': 'chatcmpl-x',
          'object': 'chat.completion.chunk',
          'choices': [
            {'index': 0, 'delta': {}, 'finish_reason': 'stop'},
          ],
        })}\n\n',
      );
      response.write('data: [DONE]\n\n');
      await response.close();
    });

    final tempHome = Directory.systemTemp.createTempSync('fa_probe_');
    File('${tempHome.path}/.fah/config.yaml')
      ..createSync(recursive: true)
      ..writeAsStringSync('''
provider: openai-completions
model: test-model
baseUrl: http://127.0.0.1:${server.port}/v1
mode: code
approvalMode: yolo
allowedTools: [read]
tui:
